content_copy
expand_less
// /content/botanical-authorities/services/wikiService.ts

export const fetchWikiImage = async (name: string): Promise<string | null> => {
  try {
    // Search for the page first
    const searchUrl = `https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(name + " botanist")}&format=json&origin=*`;
    const searchRes = await fetch(searchUrl);
    const searchData = await searchRes.json();

    if (!searchData.query.search.length) return null;

    const title = searchData.query.search[0].title;

    // Get the page image
    const imgUrl = `https://en.wikipedia.org/w/api.php?action=query&titles=${encodeURIComponent(title)}&prop=pageimages&format=json&pithumbsize=500&origin=*`;
    const imgRes = await fetch(imgUrl);
    const imgData = await imgRes.json();

    const pages = imgData.query.pages;
    const pageId = Object.keys(pages)[0];

    if (pages[pageId].thumbnail) {
      return pages[pageId].thumbnail.source;
    }
    return null;
  } catch (error) {
    console.error("Wiki image fetch failed", error);
    return null;
  }
};
Step 2: Update geminiService.ts

We will update the config to use responseMimeType: 'application/json' and lower the temperature.

code
TypeScript
download
content_copy
