// /content/botanical-authorities/services/geminiService.ts

// ... keep imports ...

export const fetchBotanistInfo = async (searchTerm: string): Promise<BotanistProfileData> => {
  if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set");
  }
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // We remove the schema from the text prompt and rely on the config
  const prompt = `Generate a detailed profile for the botanical authority: "${searchTerm}". 

  CRITICAL INSTRUCTIONS:
  1. Use the Google Search tool to verify every single Taxon and Publication.
  2. If a list item (like an eponymous taxon) cannot be verified with a citation/year, DO NOT include it.
  3. If the person is not found, return { "error": "Not found" }.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-2.0-flash", // 2.0 Flash is faster and great at JSON. Or stick to 1.5 Pro.
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json", // FORCE JSON
      responseSchema: botanistProfileSchema, // FORCE SCHEMA ADHERENCE
      temperature: 0, // REDUCE CREATIVITY/HALLUCINATION
    },
  });

  // ... The rest of your parsing logic becomes much simpler because 
  // the output is guaranteed to be JSON now ...

  let jsonText = response.text || "{}";
  let parsedData: BotanistProfileData;

  try {
      parsedData = JSON.parse(jsonText);
  } catch (e) {
      // Fallback to your sliding window parser if needed, 
      // but with responseMimeType it's rarely needed.
      console.error("JSON Parse Error", e);
      throw new Error("Failed to parse AI response.");
  }

  // ... keep your grounding metadata extraction logic ...

  return parsedData;
};
Step 3: Update BotanistProfile.tsx to show the image

Update your component to accept an image URL (which you would fetch in App.tsx in parallel with the Gemini call).

