import React, { useState, useRef } from 'react';
import { analyzeTaxon, compareTaxa } from './services/geminiService';
import { TaxonData, ComparisonData, Mode, Source } from './types';
import { 
  SearchIcon, SparklesIcon, LeafIcon, GlobeIcon, 
  BookOpenIcon, ScrollIcon, AlertTriangleIcon, ArrowRightLeftIcon, XIcon 
} from './components/Icons';
import { TaxonCard } from './components/TaxonCard';

// Placeholder examples
const EXAMPLES = ['Amanita muscaria', 'Quercus robur', 'Canis lupus', 'Monarch Butterfly', 'Eupatorieae'];

const parseInline = (text: string) => {
  if (!text) return '';
  let parsed = text;

  // Clean up leading bullets/asterisks often left by the model in table cells
  parsed = parsed.replace(/^\s*[\*•-]\s*/, '');

  // Fix: Model sometimes wraps entire line in bold: "**Habit: Description**" -> "**Habit**: Description"
  parsed = parsed.replace(/\*\*([^\*]+?)([:\-–—])\s+([^\*]+?)\*\*/g, '**$1**$2 $3');
  // Fix: Model uses * as separator inside bold: "**Habit * Description**" -> "**Habit** * Description"
  parsed = parsed.replace(/\*\*([^\*]+?)(\s+\*\s+)([^\*]+?)\*\*/g, '**$1**$2$3');

  // Bold: **text**
  parsed = parsed.replace(/\*\*([\s\S]+?)\*\*/g, '<strong class="text-cyan-300 font-semibold">$1</strong>');

  // Italic: *text*
  parsed = parsed.replace(/(^|[^\w])\*([^\*]+?)\*(?=[^\w]|$)/g, '$1<em class="text-slate-400 italic">$2</em>');

  return parsed;
};

const formatHtml = (text: string) => {
  if (!text) return { __html: '' };

  const blocks = text.split(/\n\n+/);

  const htmlBlocks = blocks.map(block => {
    let content = block.trim();
    if (!content) return '';

    // Header (### Header)
    if (content.startsWith('### ')) {
      return `<h3 class="text-lg font-semibold text-cyan-100 mt-6 mb-3 border-b border-cyan-900/20 pb-2">${parseInline(content.replace(/^###\s+/, ''))}</h3>`;
    }

    // List (starts with * or -)
    if (content.match(/^[\*\-]\s/)) {
      const items = content.split(/\n/).map(line => {
        const cleanLine = line.replace(/^[\*\-]\s+/, '').trim();
        if (!cleanLine) return '';
        return `<li class="flex items-start gap-3 mb-3 last:mb-0 group"><span class="text-cyan-400/60 mt-1.5 text-xs shrink-0 group-hover:text-cyan-400/90 transition-colors">•</span><span class="leading-relaxed">${parseInline(cleanLine)}</span></li>`;
      }).join('');
      return `<ul class="my-4 text-slate-300">${items}</ul>`;
    }

    // Key-Value pairs (e.g. "**Leaves**: description")
    if (content.match(/^\s*\*\*.*\*\*:/)) {
       return `<p class="mb-4 text-slate-300 leading-relaxed">${parseInline(content)}</p>`;
    }

    // Standard Paragraph
    return `<p class="mb-4 text-slate-300 leading-relaxed last:mb-0">${parseInline(content)}</p>`;
  });

  return { __html: htmlBlocks.join('') };
};

const SourceList: React.FC<{ sources?: Source[] }> = ({ sources }) => {
  if (!sources || sources.length === 0) return null;

  return (
    <div className="mt-10 pt-8 border-t border-slate-800/50">
      <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4 flex items-center gap-2">
        <div className="w-1 h-4 bg-cyan-500/50 rounded-full"></div>
        Verified Sources
      </h4>
      <div className="flex flex-wrap gap-2">
        {sources.map((source, idx) => (
          <a 
            key={idx} 
            href={source.uri} 
            target="_blank" 
            rel="noopener noreferrer"
            className="group text-xs text-cyan-500 hover:text-cyan-400 bg-slate-900/50 px-4 py-2 rounded-lg border border-slate-800/50 hover:border-cyan-800/50 hover:bg-slate-800/50 transition-all duration-200 truncate max-w-[220px] hover:shadow-lg hover:shadow-cyan-900/10"
            title={source.title}
          >
            <span className="flex items-center gap-2">
              <svg className="w-3 h-3 opacity-50 group-hover:opacity-100 transition-opacity" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
              </svg>
              {source.title || new URL(source.uri).hostname}
            </span>
          </a>
        ))}
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>(Mode.SINGLE);
  const [inputs, setInputs] = useState<string[]>(['']);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [singleData, setSingleData] = useState<TaxonData | null>(null);
  const [compareData, setCompareData] = useState<ComparisonData | null>(null);

  const resultsRef = useRef<HTMLDivElement>(null);

  const handleSearch = async () => {
    const validInputs = inputs.map(i => i.trim()).filter(i => i.length > 0);

    if (validInputs.length === 0) return;
    if (mode === Mode.COMPARE && validInputs.length < 2) {
      setError("Please enter at least two taxa to compare.");
      return;
    }

    setLoading(true);
    setError(null);
    setSingleData(null);
    setCompareData(null);

    try {
      if (mode === Mode.SINGLE) {
        const data = await analyzeTaxon(validInputs[0]);
        setSingleData(data);
      } else {
        const data = await compareTaxa(validInputs);
        setCompareData(data);
      }
      setTimeout(() => {
        resultsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An unexpected error occurred while fetching taxon data.");
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSearch();
  };

  const loadExample = (ex: string) => {
    setInputs([ex]);
    setMode(Mode.SINGLE);
    setSingleData(null);
    setCompareData(null);
  };

  const updateInput = (index: number, value: string) => {
    const newInputs = [...inputs];
    newInputs[index] = value;
    setInputs(newInputs);
  };

  const addInput = () => {
    if (inputs.length < 3) {
      setInputs([...inputs, '']);
    }
  };

  const removeInput = (index: number) => {
    if (inputs.length > 2) {
      const newInputs = inputs.filter((_, i) => i !== index);
      setInputs(newInputs);
    }
  };

  const toggleMode = () => {
    if (mode === Mode.SINGLE) {
      setMode(Mode.COMPARE);
      if (inputs.length < 2) {
        setInputs([inputs[0] || '', '']);
      }
    } else {
      setMode(Mode.SINGLE);
      setInputs([inputs[0] || '']);
    }
    setSingleData(null);
    setCompareData(null);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950 text-slate-200 selection:bg-cyan-500/30 pb-20">

      {/* Subtle background pattern */}
      <div className="fixed inset-0 bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-cyan-900/5 via-transparent to-transparent pointer-events-none"></div>

      {/* Header / Hero */}
      <header className="relative pt-24 pb-16 px-4 text-center max-w-5xl mx-auto">
        <div className="absolute inset-0 bg-gradient-to-b from-cyan-500/5 to-transparent blur-3xl -z-10"></div>

        <h1 className="text-6xl md:text-7xl font-bold text-white mb-6 tracking-tight">
          Taxon <span className="text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-teal-400 to-emerald-400 animate-gradient">Profiles</span>
        </h1>
        <p className="text-lg md:text-xl text-slate-400 mb-12 max-w-2xl mx-auto leading-relaxed font-light">
          Comprehensive morphological analysis, identification keys, and ecological context for taxonomic research.
        </p>

        {/* Search Container */}
        <div className="relative bg-slate-900/40 backdrop-blur-xl border border-slate-800/50 p-3 rounded-3xl shadow-2xl max-w-3xl mx-auto">
          {/* Glow effect */}
          <div className="absolute -inset-[1px] bg-gradient-to-r from-cyan-500/20 to-teal-500/20 rounded-3xl blur opacity-0 group-hover:opacity-100 transition-opacity -z-10"></div>

          {/* Inputs */}
          <div className="flex flex-col gap-3 p-3">

            {inputs.map((input, index) => (
              <div key={index} className="relative flex items-center gap-3 animate-in fade-in slide-in-from-left-4 duration-300">
                <div className="relative flex-grow group">
                  <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-cyan-500 w-5 h-5 transition-colors" />
                  <input
                    type="text"
                    value={input}
                    onChange={(e) => updateInput(index, e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder={mode === Mode.COMPARE ? `Taxon ${index + 1}` : "Enter scientific or common name..."}
                    className="w-full bg-slate-950/50 border border-slate-800/50 rounded-2xl py-4 pl-12 pr-4 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-cyan-500/30 focus:border-cyan-500/50 transition-all hover:border-slate-700/50"
                  />
                </div>

                {/* Remove Button */}
                {mode === Mode.COMPARE && index > 1 && (
                  <button 
                    onClick={() => removeInput(index)}
                    className="p-4 bg-slate-950/50 hover:bg-red-950/30 text-slate-500 hover:text-red-400 rounded-2xl border border-slate-800/50 hover:border-red-900/50 transition-all duration-200"
                    title="Remove Taxon"
                  >
                    <XIcon className="w-5 h-5" />
                  </button>
                )}
              </div>
            ))}

            {/* Add Taxon Button */}
            {mode === Mode.COMPARE && inputs.length < 3 && (
              <button
                onClick={addInput}
                className="py-3 px-4 rounded-2xl border border-dashed border-slate-800/50 text-slate-500 hover:text-cyan-400 hover:border-cyan-800/50 hover:bg-slate-900/30 transition-all text-sm font-medium"
              >
                + Add Another Taxon
              </button>
            )}

            <button
              onClick={handleSearch}
              disabled={loading}
              className="relative mt-3 bg-gradient-to-r from-cyan-600 via-cyan-500 to-teal-600 hover:from-cyan-500 hover:via-teal-500 hover:to-emerald-600 text-white font-semibold py-4 px-8 rounded-2xl transition-all duration-300 shadow-lg shadow-cyan-900/30 hover:shadow-cyan-900/50 hover:shadow-xl disabled:opacity-50 disabled:cursor-not-allowed w-full overflow-hidden group"
            >
              <div className="absolute inset-0 bg-white/10 transform scale-x-0 group-hover:scale-x-100 transition-transform origin-left duration-300"></div>
              <span className="relative">
                {loading ? (
                  <span className="flex items-center justify-center gap-2">
                    <span className="animate-spin h-4 w-4 border-2 border-white border-t-transparent rounded-full"></span>
                    Analyzing
                  </span>
                ) : (
                  mode === Mode.COMPARE ? 'Compare Taxa' : 'Analyze Taxon'
                )}
              </span>
            </button>
          </div>

          {/* Controls */}
          <div className="flex justify-center items-center py-3 border-t border-slate-800/30 mt-2">
             <button 
                onClick={toggleMode}
                className="flex items-center gap-2 text-sm font-medium text-cyan-400 hover:text-cyan-300 transition-colors group"
             >
                {mode === Mode.SINGLE ? (
                  <>
                    <ArrowRightLeftIcon className="w-4 h-4 group-hover:rotate-180 transition-transform duration-300" /> 
                    Switch to Comparison Mode
                  </>
                ) : (
                  <>
                    <XIcon className="w-4 h-4 group-hover:rotate-90 transition-transform duration-300" /> 
                    Cancel Comparison
                  </>
                )}
             </button>
          </div>
        </div>

        {/* Examples */}
        {!singleData && !compareData && !loading && (
          <div className="mt-10 flex flex-wrap justify-center gap-3 animate-in fade-in slide-in-from-bottom-4 duration-700 fill-mode-backwards delay-150">
            <span className="text-xs text-slate-500 uppercase tracking-widest mr-2 self-center">Try:</span>
            {EXAMPLES.map(ex => (
              <button 
                key={ex}
                onClick={() => loadExample(ex)}
                className="px-5 py-2 bg-slate-900/30 hover:bg-slate-800/50 border border-slate-800/30 hover:border-slate-700/50 rounded-full text-sm text-slate-400 hover:text-slate-200 transition-all duration-200 hover:shadow-lg hover:shadow-slate-900/20"
              >
                {ex}
              </button>
            ))}
          </div>
        )}
      </header>

      {/* Main Content Area */}
      <main ref={resultsRef} className="relative max-w-7xl mx-auto px-4">

        {error && (
          <div className="p-6 bg-red-950/30 backdrop-blur-sm border border-red-500/30 rounded-2xl text-red-200 text-center mb-12 max-w-4xl mx-auto animate-in fade-in slide-in-from-top-4 duration-300">
            <AlertTriangleIcon className="w-8 h-8 mx-auto mb-3 text-red-400" />
            <p className="leading-relaxed">{error}</p>
          </div>
        )}

        {/* SINGLE TAXON VIEW */}
        {singleData && !loading && (
          <div className="space-y-8 animate-in fade-in duration-500 max-w-6xl mx-auto">

            {/* Header for Result */}
            <div className="text-center mb-12 relative">
               <div className="absolute inset-0 bg-gradient-to-b from-cyan-500/5 to-transparent blur-3xl -z-10"></div>
               <h2 className="text-5xl md:text-6xl font-bold text-white mb-3 tracking-tight">
                 <i className="italic font-serif">{singleData.scientificName}</i>
               </h2>
               <p className="text-2xl text-cyan-400 font-medium mb-4">{singleData.commonName}</p>
               <span className="inline-block px-4 py-2 bg-slate-900/50 backdrop-blur-sm text-slate-400 text-xs uppercase tracking-widest rounded-xl border border-slate-800/50">
                 {singleData.family}
               </span>
            </div>

            {/* Grid Layout */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">

              {/* Quick Recap - Full Width */}
              <div className="lg:col-span-12">
                <TaxonCard 
                  title="Quick Recap" 
                  icon={<SparklesIcon className="w-5 h-5" />}
                  highlight
                >
                  <div dangerouslySetInnerHTML={formatHtml(singleData.quickRecap)} />
                </TaxonCard>
              </div>

              {/* Diagnostic Description - Main Left Column */}
              <div className="lg:col-span-8">
                <TaxonCard 
                   title="Diagnostic Features" 
                   icon={<LeafIcon className="w-5 h-5" />}
                >
                  <div dangerouslySetInnerHTML={formatHtml(singleData.diagnosticDescription)} />
                </TaxonCard>
              </div>

              {/* Sidebar - Right Column */}
              <div className="lg:col-span-4 space-y-6">

                 {/* Ecology */}
                 <TaxonCard title="Ecology & Range" icon={<GlobeIcon className="w-5 h-5" />}>
                    <div className="mb-5 last:mb-0">
                      <strong className="text-slate-200 block mb-2 text-xs font-bold uppercase tracking-widest text-cyan-400/70">Habitat</strong>
                      <div dangerouslySetInnerHTML={formatHtml(singleData.ecology)} />
                    </div>
                    <div>
                      <strong className="text-slate-200 block mb-2 text-xs font-bold uppercase tracking-widest text-cyan-400/70">Distribution</strong>
                      <div dangerouslySetInnerHTML={formatHtml(singleData.distribution)} />
                    </div>
                 </TaxonCard>

                 {/* Etymology */}
                 <TaxonCard title="Etymology" icon={<BookOpenIcon className="w-5 h-5" />}>
                    <div className="text-slate-400 text-sm leading-relaxed">
                       <span dangerouslySetInnerHTML={formatHtml(singleData.etymology)} />
                    </div>
                 </TaxonCard>

                 {/* History */}
                 <TaxonCard title="Historical Context" icon={<ScrollIcon className="w-5 h-5" />}>
                    <div className="text-slate-400 text-sm leading-relaxed" dangerouslySetInnerHTML={formatHtml(singleData.history)} />
                 </TaxonCard>

              </div>

              {/* Confused Taxa - Full Width */}
              <div className="lg:col-span-12">
                 <TaxonCard title="Similar Species" icon={<AlertTriangleIcon className="w-5 h-5" />} className="border-orange-900/20">
                    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5">
                       {singleData.confusedTaxa.map((taxon, idx) => (
                         <div key={idx} className="bg-slate-950/30 backdrop-blur-sm p-5 rounded-xl border border-slate-800/50 hover:border-orange-900/30 transition-all duration-200 hover:shadow-lg hover:shadow-orange-900/5 group">
