const EXAMPLES = ['Amanita muscaria', 'Quercus robur', 'Canis lupus', 'Monarch Butterfly', 'Eupatorieae'];

const parseInline = (text: string) => {
  if (!text) return '';
  let parsed = text;

  // Clean up leading bullets ONLY if followed by space (fixes "*Habit*:" breaking)
  parsed = parsed.replace(/^\s*[\*•-]\s+/, '');

  // Fix: Model sometimes wraps entire line in bold: "**Habit: Description**" -> "**Habit**: Description"
  parsed = parsed.replace(/\*\*([^\*]+?)([:\-–—])\s*([^\*]+?)\*\*/g, '**$1**$2 $3');
  // Fix: Model uses * as separator inside bold: "**Habit * Description**" -> "**Habit** * Description"
  parsed = parsed.replace(/\*\*([^\*]+?)(\s+\*\s+)([^\*]+?)\*\*/g, '**$1**$2$3');

  // Bold: **text** -> Cyan highlight
  parsed = parsed.replace(/\*\*([\s\S]+?)\*\*/g, '<strong class="text-cyan-400 font-semibold">$1</strong>');

  // Italic: *text* -> Inherit color (important for orange warning cards)
  parsed = parsed.replace(/(^|[^\w])\*([^\*]+?)\*(?=[^\w]|$)/g, '$1<em class="italic opacity-90">$2</em>');

  return parsed;
};

const formatHtml = (text: string) => {
  if (!text) return { __html: '' };

  const blocks = text.split(/\n\n+/);

  const htmlBlocks = blocks.map(block => {
    let content = block.trim();
    if (!content) return '';

    // Header (### Header)
    if (content.startsWith('### ')) {
      return `<h3 class="text-lg font-semibold text-cyan-100 mt-6 mb-3 border-b border-cyan-900/20 pb-2">${parseInline(content.replace(/^###\s+/, ''))}</h3>`;
    }

    // List (starts with * or -)
    if (content.match(/^[\*\-]\s/)) {
      const items = content.split(/\n/).map(line => {
        const cleanLine = line.replace(/^[\*\-]\s+/, '').trim();
        if (!cleanLine) return '';
        return `<li class="flex items-start gap-3 mb-3 last:mb-0 group"><span class="text-cyan-400/60 mt-1.5 text-xs shrink-0 group-hover:text-cyan-400/90 transition-colors">•</span><span class="leading-relaxed">${parseInline(cleanLine)}</span></li>`;
      }).join('');
      return `<ul class="my-4 text-slate-300">${items}</ul>`;
    }

    // Key-Value pairs (e.g. "**Leaves**: description")
    if (content.match(/^\s*\*\*.*\*\*:/)) {
       return `<p class="mb-4 text-slate-300 leading-relaxed">${parseInline(content)}</p>`;
    }

    // Standard Paragraph
    return `<p class="mb-4 text-slate-300 leading-relaxed last:mb-0">${parseInline(content)}</p>`;
  });

  return { __html: htmlBlocks.join('') };
};

const SourceList: React.FC<{ sources?: Source[] }> = ({ sources }) => {
  if (!sources || sources.length === 0) return null;

