                {loading ? (
                  <span className="flex items-center justify-center gap-2">
                    <span className="animate-spin h-4 w-4 border-2 border-white border-t-transparent rounded-full"></span>
                    Analyzing
                  </span>
                ) : (
                  mode === Mode.COMPARE ? 'Compare Taxa' : 'Analyze Taxon'
                )}
              </span>
            </button>
          </div>

          {/* Controls */}
          <div className="flex justify-between items-center py-3 border-t border-slate-800/30 mt-2 px-2">
             <button 
                onClick={toggleMode}
                className="flex items-center gap-2 text-sm font-medium text-cyan-400 hover:text-cyan-300 transition-colors group"
             >
                {mode === Mode.SINGLE ? (
                  <>
                    <ArrowRightLeftIcon className="w-4 h-4 group-hover:rotate-180 transition-transform duration-300" /> 
