const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>(Mode.SINGLE);
  const [inputs, setInputs] = useState<string[]>(['']);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [singleData, setSingleData] = useState<TaxonData | null>(null);
  const [compareData, setCompareData] = useState<ComparisonData | null>(null);

  const resultsRef = useRef<HTMLDivElement>(null);

  const handleSearch = async () => {
    const validInputs = inputs.map(i => i.trim()).filter(i => i.length > 0);

    if (validInputs.length === 0) return;
    if (mode === Mode.COMPARE && validInputs.length < 2) {
      setError("Please enter at least two taxa to compare.");
      return;
    }

    setLoading(true);
    setError(null);
    setSingleData(null);
    setCompareData(null);

    try {
      if (mode === Mode.SINGLE) {
        const data = await analyzeTaxon(validInputs[0]);
        setSingleData(data);
      } else {
        const data = await compareTaxa(validInputs);
        setCompareData(data);
      }
      setTimeout(() => {
        resultsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An unexpected error occurred while fetching taxon data.");
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSearch();
  };

  const loadExample = (ex: string) => {
    setInputs([ex]);
    setMode(Mode.SINGLE);
    setSingleData(null);
    setCompareData(null);
  };

  const updateInput = (index: number, value: string) => {
    const newInputs = [...inputs];
    newInputs[index] = value;
    setInputs(newInputs);
  };

  const addInput = () => {
    if (inputs.length < 3) {
      setInputs([...inputs, '']);
    }
  };

  const removeInput = (index: number) => {
    if (inputs.length > 2) {
      const newInputs = inputs.filter((_, i) => i !== index);
      setInputs(newInputs);
    }
  };

  const toggleMode = () => {
    if (mode === Mode.SINGLE) {
      setMode(Mode.COMPARE);
      if (inputs.length < 2) {
        setInputs([inputs[0] || '', '']);
      }
    } else {
      setMode(Mode.SINGLE);
      setInputs([inputs[0] || '']);
    }
    setSingleData(null);
    setCompareData(null);
  };

  const handlePrint = () => {
    const content = resultsRef.current;
    if (!content) return;

    // Use a new window to bypass iframe print restrictions and control the print layout strictly
    const printWindow = window.open('', '_blank', 'height=800,width=900');

    if (!printWindow) {
      alert("Please allow pop-ups for this site to enable the print view.");
      return;
    }

    // Collect styles to maintain formatting
    const styles = Array.from(document.querySelectorAll('style, link[rel="stylesheet"]'))
      .map(style => style.outerHTML)
      .join('');

    // Collect tailwind script to ensure utility classes work in the new window
    const scripts = Array.from(document.querySelectorAll('script[src*="tailwindcss"]'))
      .map(script => script.outerHTML)
      .join('');

    const html = `
      <!DOCTYPE html>
      <html lang="en">
        <head>
          <meta charset="UTF-8">
          <title>Taxon Profile - Print View</title>
          ${styles}
          ${scripts}
          <link rel="preconnect" href="https://fonts.googleapis.com">
          <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
          <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Merriweather:ital,wght@0,300;0,400;0,700;1,400&display=swap" rel="stylesheet">
          <style>
            body { 
              background-color: white !important; 
              color: black !important; 
              font-family: 'Inter', sans-serif;
              padding: 40px;
            }
            .print-container {
              max-width: 900px;
              margin: 0 auto;
            }
            /* Force colors for print readability */
            * {
              text-shadow: none !important;
              box-shadow: none !important;
              color: black !important;
              border-color: #ccc !important;
            }
            /* Adjust specific elements from the dark theme */
            strong.text-cyan-400, span.text-cyan-400 {
              color: #000 !important;
              font-weight: 700 !important;
            }
            .bg-slate-900, .bg-slate-950, .bg-slate-800 {
              background-color: white !important;
              border: 1px solid #ddd !important;
            }
            a { text-decoration: underline !important; color: #000 !important; }
            h1, h2, h3 { color: #000 !important; page-break-after: avoid; }
            img, svg { filter: grayscale(100%); }

            /* Hide non-print elements that might have been copied */
            .no-print { display: none !important; }
          </style>
        </head>
        <body>
          <div class="print-container">
            <h1 style="font-family: Merriweather, serif; font-size: 24px; margin-bottom: 20px; border-bottom: 2px solid black; padding-bottom: 10px;">
              Taxon Profile Report
            </h1>
            ${content.innerHTML}
            <div style="margin-top: 40px; font-size: 10px; border-top: 1px solid #ccc; padding-top: 10px; text-align: center;">
              Generated by Taxon Profiles AI • ${new Date().toLocaleDateString()}
            </div>
          </div>
          <script>
            // Wait for Tailwind and fonts to parse
            window.onload = () => {
              setTimeout(() => {
                window.print();
                // We keep the window open so the user can verify, or they can close it.
              }, 800);
            };
          </script>
        </body>
      </html>
    `;

    printWindow.document.write(html);
    printWindow.document.close();
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950 text-slate-200 selection:bg-cyan-500/30 pb-20 print:bg-white print:text-black print:pb-0">

      {/* Subtle background pattern - Hidden on print */}
      <div className="fixed inset-0 bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-cyan-900/5 via-transparent to-transparent pointer-events-none print:hidden"></div>

      {/* Header / Hero */}
      <header className="relative pt-24 pb-16 px-4 text-center max-w-5xl mx-auto print:pt-4 print:pb-8">
        <div className="absolute inset-0 bg-gradient-to-b from-cyan-500/5 to-transparent blur-3xl -z-10 print:hidden"></div>

        <h1 className="text-6xl md:text-7xl font-bold text-white mb-6 tracking-tight print:text-black print:text-4xl print:mb-2">
          Taxon <span className="text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-teal-400 to-emerald-400 animate-gradient print:text-black print:bg-none">Profiles</span>
        </h1>
        <p className="text-lg md:text-xl text-slate-400 mb-12 max-w-2xl mx-auto leading-relaxed font-light print:text-black print:text-sm print:mb-4">
          Highlighting key morphological characters for identification, differentiation from similar taxa, and providing essential background information.
        </p>

        {/* Search Container - Hidden on print */}
        <div className="relative bg-slate-900/40 backdrop-blur-xl border border-slate-800/50 p-3 rounded-3xl shadow-2xl max-w-3xl mx-auto print:hidden">
          {/* Glow effect */}
          <div className="absolute -inset-[1px] bg-gradient-to-r from-cyan-500/20 to-teal-500/20 rounded-3xl blur opacity-0 group-hover:opacity-100 transition-opacity -z-10"></div>

          {/* Inputs */}
          <div className="flex flex-col gap-3 p-3">

            {inputs.map((input, index) => (
              <div key={index} className="relative flex items-center gap-3 animate-in fade-in slide-in-from-left-4 duration-300">
                <div className="relative flex-grow group">
                  <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-cyan-500 w-5 h-5 transition-colors" />
                  <input
                    type="text"
                    value={input}
                    onChange={(e) => updateInput(index, e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder={mode === Mode.COMPARE ? `Taxon ${index + 1}` : "Enter scientific or common name..."}
                    className="w-full bg-slate-950/50 border border-slate-800/50 rounded-2xl py-4 pl-12 pr-4 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-cyan-500/30 focus:border-cyan-500/50 transition-all hover:border-slate-700/50"
                  />
                </div>

                {/* Remove Button */}
                {mode === Mode.COMPARE && index > 1 && (
                  <button 
                    onClick={() => removeInput(index)}
                    className="p-4 bg-slate-950/50 hover:bg-red-950/30 text-slate-500 hover:text-red-400 rounded-2xl border border-slate-800/50 hover:border-red-900/50 transition-all duration-200"
                    title="Remove Taxon"
                  >
                    <XIcon className="w-5 h-5" />
                  </button>
                )}
              </div>
            ))}

            {/* Add Taxon Button */}
            {mode === Mode.COMPARE && inputs.length < 3 && (
              <button
                onClick={addInput}
                className="py-3 px-4 rounded-2xl border border-dashed border-slate-800/50 text-slate-500 hover:text-cyan-400 hover:border-cyan-800/50 hover:bg-slate-900/30 transition-all text-sm font-medium"
              >
                + Add Another Taxon
              </button>
            )}

            <button
              onClick={handleSearch}
              disabled={loading}
              className="relative mt-3 bg-gradient-to-r from-cyan-600 via-cyan-500 to-teal-600 hover:from-cyan-500 hover:via-teal-500 hover:to-emerald-600 text-white font-semibold py-4 px-8 rounded-2xl transition-all duration-300 shadow-lg shadow-cyan-900/30 hover:shadow-cyan-900/50 hover:shadow-xl disabled:opacity-50 disabled:cursor-not-allowed w-full overflow-hidden group"
            >
              <div className="absolute inset-0 bg-white/10 transform scale-x-0 group-hover:scale-x-100 transition-transform origin-left duration-300"></div>
              <span className="relative">
                {loading ? (
                  <span className="flex items-center justify-center gap-2">
                    <span className="animate-spin h-4 w-4 border-2 border-white border-t-transparent rounded-full"></span>
                    Analyzing
                  </span>
                ) : (
                  mode === Mode.COMPARE ? 'Compare Taxa' : 'Analyze Taxon'
                )}
              </span>
            </button>
          </div>

          {/* Controls */}
          <div className="flex justify-between items-center py-3 border-t border-slate-800/30 mt-2 px-2">
             <button 
                onClick={toggleMode}
                className="flex items-center gap-2 text-sm font-medium text-cyan-400 hover:text-cyan-300 transition-colors group"
             >
                {mode === Mode.SINGLE ? (
                  <>
                    <ArrowRightLeftIcon className="w-4 h-4 group-hover:rotate-180 transition-transform duration-300" /> 
                    Switch to Comparison Mode
                  </>
                ) : (
                  <>
                    <XIcon className="w-4 h-4 group-hover:rotate-90 transition-transform duration-300" /> 
                    Cancel Comparison
                  </>
                )}
             </button>

             {/* Print Button */}
             {(singleData || compareData) && (
               <button
                 type="button"
                 onClick={handlePrint}
                 className="flex items-center gap-2 text-sm font-medium text-slate-400 hover:text-white transition-colors"
                 title="Open Print View in New Window"
               >
                 <PrinterIcon className="w-4 h-4" />
                 Print / PDF
               </button>
             )}
          </div>
        </div>

        {/* Examples */}
        {!singleData && !compareData && !loading && (
          <div className="mt-10 flex flex-wrap justify-center gap-3 animate-in fade-in slide-in-from-bottom-4 duration-700 fill-mode-backwards delay-150 print:hidden">
            <span className="text-xs text-slate-500 uppercase tracking-widest mr-2 self-center">Try:</span>
            {EXAMPLES.map(ex => (
              <button 
                key={ex}
                onClick={() => loadExample(ex)}
                className="px-5 py-2 bg-slate-900/30 hover:bg-slate-800/50 border border-slate-800/30 hover:border-slate-700/50 rounded-full text-sm text-slate-400 hover:text-slate-200 transition-all duration-200 hover:shadow-lg hover:shadow-slate-900/20"
              >
                {ex}
              </button>
            ))}
          </div>
        )}
      </header>

      {/* Main Content Area */}
      <main ref={resultsRef} className="relative max-w-7xl mx-auto px-4 print:px-0">

        {error && (
          <div className="p-6 bg-red-950/30 backdrop-blur-sm border border-red-500/30 rounded-2xl text-red-200 text-center mb-12 max-w-4xl mx-auto animate-in fade-in slide-in-from-top-4 duration-300 print:hidden">
            <AlertTriangleIcon className="w-8 h-8 mx-auto mb-3 text-red-400" />
            <p className="leading-relaxed">{error}</p>
          </div>
        )}

        {/* SINGLE TAXON VIEW */}
        {singleData && !loading && (
          <div className="space-y-8 animate-in fade-in duration-500 max-w-6xl mx-auto">

            {/* Header for Result */}
            <div className="text-center mb-12 relative print:mb-6">
               <div className="absolute inset-0 bg-gradient-to-b from-cyan-500/5 to-transparent blur-3xl -z-10 print:hidden"></div>
               <h2 className="text-5xl md:text-6xl font-bold text-white mb-3 tracking-tight print:text-black print:text-3xl">
                 <i className="italic font-serif">{singleData.scientificName}</i>
                 {singleData.author && (
                   <span className="block mt-2 text-2xl text-slate-400 font-normal not-italic print:text-black print:text-lg">
                     {singleData.author}
                   </span>
                 )}
               </h2>
               <p className="text-2xl text-cyan-400 font-medium mb-4 print:text-black print:text-xl">{singleData.commonName}</p>
               <span className="inline-block px-4 py-2 bg-slate-900/50 backdrop-blur-sm text-slate-400 text-xs uppercase tracking-widest rounded-xl border border-slate-800/50 print:bg-white print:text-black print:border-gray-400">
                 {singleData.family}
               </span>
            </div>

            {/* Grid Layout */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">

              {/* Quick Recap - Full Width */}
              <div className="lg:col-span-12">
                <TaxonCard 
                  title="Quick Recap" 
                  icon={<StarIcon className="w-5 h-5" />}
                  highlight
                >
                  <div dangerouslySetInnerHTML={formatHtml(singleData.quickRecap)} />
                </TaxonCard>
              </div>

              {/* Diagnostic Description - Main Left Column */}
              <div className="lg:col-span-8">
                <TaxonCard 
                   title="Diagnostic Features" 
                   icon={<LeafIcon className="w-5 h-5" />}
                >
                  <div dangerouslySetInnerHTML={formatHtml(singleData.diagnosticDescription)} />
                </TaxonCard>
              </div>

              {/* Sidebar - Right Column */}
              <div className="lg:col-span-4 space-y-6">

                 {/* Ecology */}
                 <TaxonCard title="Ecology & Range" icon={<GlobeIcon className="w-5 h-5" />}>
                    <div className="mb-5 last:mb-0">
                      <strong className="text-slate-200 block mb-2 text-xs font-bold uppercase tracking-widest text-cyan-400/70 print:text-black">Habitat</strong>
                      <div dangerouslySetInnerHTML={formatHtml(singleData.ecology)} />
                    </div>
                    <div>
                      <strong className="text-slate-200 block mb-2 text-xs font-bold uppercase tracking-widest text-cyan-400/70 print:text-black">Distribution</strong>
                      <div dangerouslySetInnerHTML={formatHtml(singleData.distribution)} />
                    </div>
                 </TaxonCard>

                 {/* Etymology */}
                 <TaxonCard title="Etymology" icon={<BookOpenIcon className="w-5 h-5" />}>
                    <div className="text-slate-400 text-sm leading-relaxed print:text-black">
                       <span dangerouslySetInnerHTML={formatHtml(singleData.etymology)} />
                    </div>
                 </TaxonCard>

                 {/* History */}
                 <TaxonCard title="Historical Context" icon={<ScrollIcon className="w-5 h-5" />}>
                    <div className="text-slate-400 text-sm leading-relaxed print:text-black" dangerouslySetInnerHTML={formatHtml(singleData.history)} />
                 </TaxonCard>

              </div>

              {/* Confused Taxa - Full Width */}
              <div className="lg:col-span-12">
                 <TaxonCard title="Similar Species" icon={<AlertTriangleIcon className="w-5 h-5" />} className="border-orange-900/20 print:border-gray-300">
                    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5">
                       {singleData.confusedTaxa.map((taxon, idx) => (
                         <div key={idx} className="bg-slate-950/30 backdrop-blur-sm p-5 rounded-xl border border-slate-800/50 hover:border-orange-900/30 transition-all duration-200 hover:shadow-lg hover:shadow-orange-900/5 group print:bg-white print:border-gray-300 print:shadow-none">
                            <h4 className="font-bold text-orange-300 mb-3 italic text-lg group-hover:text-orange-200 transition-colors print:text-black">{taxon.name}</h4>
                            <div className="text-sm text-slate-400 mb-3 leading-relaxed print:text-black" dangerouslySetInnerHTML={formatHtml(taxon.difference)} />
                            <div className="pt-3 border-t border-slate-800/50 print:border-gray-300">
                              <span className="text-xs text-orange-400/70 uppercase tracking-wide font-semibold print:text-black">Key Feature: </span>
                              <span className="text-xs text-orange-300 print:text-black" dangerouslySetInnerHTML={{ __html: parseInline(taxon.keyFeature.replace(/^(Key Feature|Check)[:\s]*/i, '')) }} />
                            </div>
                         </div>
                       ))}
                    </div>
                 </TaxonCard>
              </div>

              {/* Sources */}
              {singleData.sources && singleData.sources.length > 0 && (
                 <div className="lg:col-span-12">
                    <SourceList sources={singleData.sources} />
                 </div>
              )}
            </div>
          </div>
        )}


        {/* COMPARISON VIEW */}
        {compareData && !loading && (
          <div className="animate-in fade-in duration-500">

             {/* Dynamic Header Grid */}
             <div className={`grid gap-6 mb-10 text-center ${
               compareData.taxa.length === 3 ? 'grid-cols-1 md:grid-cols-3' : 'grid-cols-1 md:grid-cols-2'
             }`}>
                {compareData.taxa.map((taxon, idx) => (
                  <div key={idx} className="relative p-8 bg-slate-900/40 backdrop-blur-sm rounded-3xl border border-slate-800/50 hover:border-slate-700/50 transition-all duration-200 flex flex-col justify-center h-full group hover:shadow-xl hover:shadow-cyan-900/10 print:bg-white print:border-gray-300 print:shadow-none print:p-4">
                     <div className="absolute inset-0 bg-gradient-to-br from-cyan-500/5 to-transparent rounded-3xl opacity-0 group-hover:opacity-100 transition-opacity duration-300 print:hidden"></div>
                     <h2 className="relative text-3xl md:text-4xl font-bold italic text-white mb-2 font-serif print:text-black print:text-2xl">{taxon.scientificName}</h2>
                     {taxon.author && (
                       <p className="relative text-md text-slate-400 mb-2 font-normal print:text-black print:text-sm">{taxon.author}</p>
                     )}
                     <p className="relative text-xl text-cyan-400 font-medium print:text-black print:text-lg">{taxon.commonName}</p>
                  </div>
                ))}
             </div>

             {/* Key Differences Table */}
             <div className="mb-10">
                <div className="bg-slate-900/40 backdrop-blur-sm border border-slate-800/50 rounded-3xl overflow-hidden shadow-2xl print:bg-white print:border-gray-300 print:shadow-none">
                   <div className="bg-gradient-to-r from-slate-900 to-slate-800/50 p-6 text-center border-b border-slate-800/50 print:bg-white print:border-gray-300">
                      <h3 className="text-xl font-bold text-white flex items-center justify-center gap-3 print:text-black">
                         <div className="w-1 h-6 bg-gradient-to-b from-cyan-400 to-teal-400 rounded-full print:hidden"></div>
                         Key Diagnostic Characters
                         <div className="w-1 h-6 bg-gradient-to-b from-teal-400 to-cyan-400 rounded-full print:hidden"></div>
                      </h3>
                   </div>
                   <div className="overflow-x-auto">
                     <table className="w-full text-left text-slate-300 text-sm min-w-[600px] print:text-black">
                        <thead className="bg-slate-950/50 text-slate-400 text-xs uppercase tracking-wider print:bg-gray-100 print:text-black">
                           <tr>
                              <th className="p-5 font-semibold w-1/4 sticky left-0 bg-slate-950/50 backdrop-blur-sm z-10 border-r border-slate-800/50 print:bg-white print:border-gray-300">Character</th>
                              {compareData.taxa.map((taxon, idx) => (
                                <th key={idx} className="p-5 font-semibold italic print:border-l print:border-gray-300">
                                  {taxon.scientificName}
                                </th>
                              ))}
                           </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-800/30 print:divide-gray-300">
                           {compareData.keyDifferences.map((diff, idx) => (
                              <tr key={idx} className="hover:bg-slate-800/20 transition-colors duration-150 print:hover:bg-transparent">
                                 <td className="p-5 font-medium text-cyan-300 sticky left-0 bg-slate-900/40 backdrop-blur-sm border-r border-slate-800/30 print:bg-white print:text-black print:border-gray-300">
                                   {diff.feature}
                                 </td>
                                 {diff.states.map((state, sIdx) => (
                                   <td key={sIdx} className="p-5 border-l border-slate-800/20 align-top print:border-gray-300">
                                     <div dangerouslySetInnerHTML={{ __html: parseInline(state) }} />
                                   </td>
                                 ))}
                              </tr>
                           ))}
                        </tbody>
                     </table>
                   </div>
                </div>
             </div>

             {/* Detailed Side-by-Side */}
             <div className={`grid gap-6 items-start ${
               compareData.taxa.length === 3 ? 'grid-cols-1 lg:grid-cols-3' : 'grid-cols-1 lg:grid-cols-2'
             }`}>
                <div className={compareData.taxa.length === 3 ? 'lg:col-span-3' : 'lg:col-span-2'}>
                   <h3 className="text-2xl font-bold text-white mb-6 border-b border-slate-800/50 pb-4 flex items-center gap-3 print:text-black print:border-gray-300">
                     <div className="w-1 h-7 bg-gradient-to-b from-cyan-400 to-teal-400 rounded-full print:hidden"></div>
                     Detailed Comparisons
                   </h3>
                </div>

                <TaxonCard title="Overview" icon={<LeafIcon className="w-5 h-5"/>} className={compareData.taxa.length === 3 ? 'lg:col-span-3' : 'lg:col-span-2'}>
                   <div className={`grid gap-6 ${compareData.taxa.length === 3 ? 'lg:grid-cols-3' : 'lg:grid-cols-2'}`}>
                     {compareData.taxa.map((taxon, idx) => (
                       <div key={idx} className="border-l-2 border-cyan-500/30 pl-5 hover:border-cyan-400/50 transition-colors print:border-gray-300">
                         <h4 className="font-bold text-white mb-3 italic text-lg print:text-black">{taxon.scientificName}</h4>
                         <div dangerouslySetInnerHTML={formatHtml(taxon.quickRecap)} />
                       </div>
                     ))}
                   </div>
                </TaxonCard>

                <TaxonCard title="Ecology" icon={<GlobeIcon className="w-5 h-5"/>} className={compareData.taxa.length === 3 ? 'lg:col-span-3' : 'lg:col-span-2'}>
                   <div className={`grid gap-6 ${compareData.taxa.length === 3 ? 'lg:grid-cols-3' : 'lg:grid-cols-2'}`}>
                     {compareData.taxa.map((taxon, idx) => (
                       <div key={idx} className="border-l-2 border-teal-500/30 pl-5 hover:border-teal-400/50 transition-colors print:border-gray-300">
                         <h4 className="font-bold text-white mb-3 italic text-lg print:text-black">{taxon.scientificName}</h4>
                         <div dangerouslySetInnerHTML={formatHtml(taxon.ecology)} />
                       </div>
                     ))}
                   </div>
                </TaxonCard>
             </div>

             {/* Sources */}
             {compareData.sources && compareData.sources.length > 0 && (
                <div className="mt-10">
                   <SourceList sources={compareData.sources} />
                </div>
             )}
          </div>
        )}

      </main>

      <footer className="relative mt-24 max-w-6xl mx-auto px-4 text-center py-10 border-t border-slate-800/30 print:border-gray-300 print:mt-10 print:py-4">
        <p className="text-slate-500 text-sm mb-3 font-light print:text-black">
           Developed by Daniel Cahen • Powered by Gemini 3 Pro Preview with integrated search verification
        </p>
        <p className="text-slate-600 text-xs print:text-black">
           Information is AI-generated and should be verified for critical identification purposes.
        </p>
      </footer>
    </div>
  );
};

export default App;
